    def pools(
        self,
        *,
        buy_tax: RangeFilter | None = None,
        buys: TimeframedRangeFilter | None = None,
        dexes: Sequence[str] | None = None,
        fdv_in_usd: RangeFilter | None = None,
        good_gt_score: bool | None = None,
        has_social: bool | None = None,
        holder_count: RangeFilter | None = None,
        liquidity: RangeFilter | None = None,
        mc_in_usd: RangeFilter | None = None,
        networks: Sequence[str] | None = None,
        no_honeypot: bool | None = None,
        on_coingecko: bool | None = None,
        page: int = 1,
        pool_creation_hours_ago: RangeFilter | None = None,
        sell_tax: RangeFilter | None = None,
        sells: TimeframedRangeFilter | None = None,
        sort: PoolSortParam | None = None,
        top_10_holders_percentage: RangeFilter | None = None,
        tx_count: TimeframedRangeFilter | None = None,
        volume_24h: RangeFilter | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> PoolsResponse:
        """Screen pools across every chain by liquidity, volume, age, holders, taxes and trade counts. Costs 2 credits.

        Args:
            buy_tax: Buy tax percentage.
            buys: Buy count over the chosen window.
            dexes: Restrict to these DEX identifiers.
            fdv_in_usd: Fully diluted valuation in USD.
            good_gt_score: Only pools above GeckoTerminal's GT score threshold.
            has_social: Only pools whose token declares social links.
            holder_count: Number of token holders.
            liquidity: Pool liquidity in USD.
            mc_in_usd: Market cap in USD.
            networks: Restrict to these network identifiers.
            no_honeypot: Exclude tokens flagged as honeypots.
            on_coingecko: Only pools whose token is listed on CoinGecko.
            page: 1-based result page.
            pool_creation_hours_ago: Pool age in hours.
            sell_tax: Sell tax percentage.
            sells: Sell count over the chosen window.
            sort: Ranking applied before pagination. Omit for GeckoTerminal's
                default.
            top_10_holders_percentage: Share of supply held by the ten largest
                holders.
            tx_count: Transaction count over the chosen window.
            volume_24h: 24h traded volume in USD.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.geckoterminal.PoolsResponse`.
        """
        return self._send(
            _pools(
                buy_tax=buy_tax,
                buys=buys,
                dexes=dexes,
                fdv_in_usd=fdv_in_usd,
                good_gt_score=good_gt_score,
                has_social=has_social,
                holder_count=holder_count,
                liquidity=liquidity,
                mc_in_usd=mc_in_usd,
                networks=networks,
                no_honeypot=no_honeypot,
                on_coingecko=on_coingecko,
                page=page,
                pool_creation_hours_ago=pool_creation_hours_ago,
                sell_tax=sell_tax,
                sells=sells,
                sort=sort,
                top_10_holders_percentage=top_10_holders_percentage,
                tx_count=tx_count,
                volume_24h=volume_24h,
            ),
            timeout=timeout,
        )

